/* ============================== PAGE-WIDE NETWORK BACKDROP ============================== */
function NetworkCanvas({ density = 40, opacity = 1, className = "" }) {
  const canvasRef = useRef(null);
  const mouseRef = useRef({ x: -9999, y: -9999 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let width, height, nodes, raf;

    const resize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };
    const initNodes = () => {
      const count = Math.round((width * height) / 32000) + Math.min(density, 24);
      nodes = Array.from({ length: Math.min(count, 80) }, () => ({
        x: Math.random() * width, y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.2, vy: (Math.random() - 0.5) * 0.2,
        r: Math.random() * 1.5 + 0.8,
      }));
    };
    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      for (const n of nodes) {
        n.x += n.vx; n.y += n.vy;
        const dxm = n.x - mouseRef.current.x, dym = n.y - mouseRef.current.y;
        const dm = Math.sqrt(dxm * dxm + dym * dym);
        if (dm < 100) { n.x += dxm / dm * 0.35; n.y += dym / dm * 0.35; }
        if (n.x < 0 || n.x > width) n.vx *= -1;
        if (n.y < 0 || n.y > height) n.vy *= -1;
      }
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const a = nodes[i], b = nodes[j];
          const dx = a.x - b.x, dy = a.y - b.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 140) {
            ctx.strokeStyle = `rgba(154,163,245,${0.1 * (1 - dist / 140)})`;
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
          }
        }
      }
      for (const n of nodes) {
        ctx.beginPath(); ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(112,140,222,0.55)"; ctx.fill();
      }
      if (!reduce) raf = requestAnimationFrame(draw);
    };

    resize(); initNodes(); draw();
    const onResize = () => { resize(); initNodes(); };
    const onMove = (e) => { mouseRef.current = { x: e.clientX, y: e.clientY }; };
    const onLeave = () => { mouseRef.current = { x: -9999, y: -9999 }; };
    window.addEventListener("resize", onResize);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseleave", onLeave);
    return () => {
      window.removeEventListener("resize", onResize);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [density]);

  return <canvas ref={canvasRef} className={className} style={{ opacity }} />;
}

function QuantumFluxCanvas({ className = "", speed = 1, opacity = 1, hero = false }) {
  const canvasRef = useRef(null);
  const containerRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return undefined;

    let raf = 0;
    let mouseX = 0;
    let mouseY = 0;
    let targetX = 0;
    let targetY = 0;
    let width = 1;
    let height = 1;

    const scene = new THREE.Scene();
    scene.background = null;
    scene.fog = new THREE.FogExp2(0x050505, 0.04);

    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 100);
    camera.position.z = hero ? 8.2 : 7;

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: false,
      powerPreference: "high-performance",
      alpha: true,
    });
    renderer.setClearColor(0x050505, hero ? 0 : 1);
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1;

    const mainGroup = new THREE.Group();
    mainGroup.scale.setScalar(hero ? 0.9 : 1);
    scene.add(mainGroup);

    const vortexCount = hero ? 6200 : 9500;
    const vortexPositions = new Float32Array(vortexCount * 3);
    const vortexRadius = new Float32Array(vortexCount);
    const vortexAngle = new Float32Array(vortexCount);
    const vortexHeight = new Float32Array(vortexCount);
    const vortexSpeed = new Float32Array(vortexCount);

    for (let i = 0; i < vortexCount; i += 1) {
      const i3 = i * 3;
      const y = (Math.random() - 0.5) * 7.5;
      const funnel = 0.4 + Math.abs(y) * 0.2;
      const r = (0.1 + Math.pow(Math.random(), 1.5) * 2.5) * funnel;
      const a = Math.random() * Math.PI * 2;
      vortexHeight[i] = y;
      vortexRadius[i] = r;
      vortexAngle[i] = a;
      vortexSpeed[i] = 0.5 + Math.random() * 0.8;
      vortexPositions[i3] = Math.cos(a) * r;
      vortexPositions[i3 + 1] = y;
      vortexPositions[i3 + 2] = Math.sin(a) * r;
    }

    const vortexGeometry = new THREE.BufferGeometry();
    vortexGeometry.setAttribute("position", new THREE.BufferAttribute(vortexPositions, 3));
    const vortexMaterial = new THREE.PointsMaterial({
      size: hero ? 0.007 : 0.006,
      color: 0xdddddd,
      transparent: true,
      opacity: hero ? 0.5 : 0.62,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const vortexPoints = new THREE.Points(vortexGeometry, vortexMaterial);
    mainGroup.add(vortexPoints);

    const createSpiralLine = (turnOffset, color, lineOpacity) => {
      const spiralPoints = [];
      const pointCount = 400;
      for (let i = 0; i < pointCount; i += 1) {
        const t = i / (pointCount - 1);
        const angle = t * Math.PI * 14 + turnOffset;
        const radius = 0.2 + t * 2.8;
        const y = (0.5 - t) * 6;
        spiralPoints.push(new THREE.Vector3(Math.cos(angle) * radius, y, Math.sin(angle) * radius));
      }
      const spiralGeometry = new THREE.BufferGeometry().setFromPoints(spiralPoints);
      const spiralMaterial = new THREE.LineBasicMaterial({
        color,
        transparent: true,
        opacity: lineOpacity,
        blending: THREE.AdditiveBlending,
      });
      const line = new THREE.Line(spiralGeometry, spiralMaterial);
      mainGroup.add(line);
      return { line, spiralGeometry, spiralMaterial };
    };

    const spiralA = createSpiralLine(0, 0x555555, hero ? 0.1 : 0.15);
    const spiralB = createSpiralLine(Math.PI, 0xdddddd, hero ? 0.13 : 0.18);

    const ambientCount = hero ? 180 : 300;
    const ambientGeometry = new THREE.BufferGeometry();
    const ambientPositions = new Float32Array(ambientCount * 3);
    for (let i = 0; i < ambientPositions.length; i += 1) {
      ambientPositions[i] = (Math.random() - 0.5) * 12;
    }
    ambientGeometry.setAttribute("position", new THREE.BufferAttribute(ambientPositions, 3));
    const ambientMaterial = new THREE.PointsMaterial({
      size: hero ? 0.006 : 0.008,
      color: 0x777777,
      transparent: true,
      opacity: hero ? 0.26 : 0.4,
      blending: THREE.AdditiveBlending,
    });
    const ambientMesh = new THREE.Points(ambientGeometry, ambientMaterial);
    scene.add(ambientMesh);

    const renderScene = new RenderPass(scene, camera);
    const bloomPass = new UnrealBloomPass(new THREE.Vector2(1, 1), 1, 0.4, 0.85);
    bloomPass.strength = 0.6;
    bloomPass.radius = 0.3;
    bloomPass.threshold = 0.2;
    const composer = hero ? null : new EffectComposer(renderer);
    if (composer) {
      composer.addPass(renderScene);
      composer.addPass(bloomPass);
    }

    const resize = () => {
      const rect = container.getBoundingClientRect();
      width = Math.max(1, rect.width);
      height = Math.max(1, rect.height);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.setSize(width, height, false);
      if (composer) composer.setSize(width, height);
    };

    const onMove = (event) => {
      const rect = container.getBoundingClientRect();
      mouseX = event.clientX - (rect.left + width / 2);
      mouseY = event.clientY - (rect.top + height / 2);
    };

    const clock = new THREE.Clock();
    const animate = () => {
      const elapsedTime = clock.getElapsedTime() * speed;
      targetX = mouseX * 0.001;
      targetY = mouseY * 0.0008;

      mainGroup.rotation.y += 0.002 * speed;
      mainGroup.rotation.y += 0.03 * (targetX - mainGroup.rotation.y);
      mainGroup.rotation.x += 0.03 * (targetY - mainGroup.rotation.x);

      const positions = vortexGeometry.attributes.position.array;
      for (let i = 0; i < vortexCount; i += 1) {
        const i3 = i * 3;
        const spin = elapsedTime * vortexSpeed[i] * 0.5 + vortexHeight[i] * 0.5;
        const angle = vortexAngle[i] + spin;
        const pulse = Math.sin(elapsedTime * 1.2 + i * 0.01) * 0.05;
        const radius = vortexRadius[i] + pulse;
        positions[i3] = Math.cos(angle) * radius;
        positions[i3 + 1] = vortexHeight[i] + Math.sin(elapsedTime + i * 0.02) * 0.03;
        positions[i3 + 2] = Math.sin(angle) * radius;
      }
      vortexGeometry.attributes.position.needsUpdate = true;

      spiralA.line.rotation.y = elapsedTime * 0.15;
      spiralB.line.rotation.y = -elapsedTime * 0.12;
      ambientMesh.rotation.y = elapsedTime * 0.03;
      ambientMesh.rotation.x = -mouseY * 0.0001;

      if (composer) {
        composer.render();
      } else {
        renderer.clear();
        renderer.render(scene, camera);
      }
      raf = requestAnimationFrame(animate);
    };

    resize();
    animate();
    const observer = new ResizeObserver(resize);
    observer.observe(container);
    window.addEventListener("mousemove", onMove);

    return () => {
      cancelAnimationFrame(raf);
      observer.disconnect();
      window.removeEventListener("mousemove", onMove);
      mainGroup.remove(vortexPoints, spiralA.line, spiralB.line);
      scene.remove(mainGroup, ambientMesh);
      vortexGeometry.dispose();
      vortexMaterial.dispose();
      spiralA.spiralGeometry.dispose();
      spiralA.spiralMaterial.dispose();
      spiralB.spiralGeometry.dispose();
      spiralB.spiralMaterial.dispose();
      ambientGeometry.dispose();
      ambientMaterial.dispose();
      if (composer) composer.dispose();
      renderer.dispose();
    };
  }, [speed, hero]);

  return (
    <div ref={containerRef} className={className} style={{ opacity, mixBlendMode: hero ? "screen" : "normal" }}>
      <canvas ref={canvasRef} className="h-full w-full outline-none" />
    </div>
  );
}

