/* ============================== RADIAL METRIC ============================== */
function RadialMetric({ value, label, trigger }) {
  const safeValue = Number.isFinite(value) ? value : 0;
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!trigger) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { setVal(safeValue); return; }
    let start = null;
    let raf;
    const step = (ts) => {
      if (!start) start = ts;
      const p = Math.min(1, (ts - start) / 1400);
      const eased = 1 - Math.pow(1 - p, 3);
      setVal(+(eased * safeValue).toFixed(2));
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => { if (raf) cancelAnimationFrame(raf); };
  }, [trigger, safeValue]);
  const displayVal = Number.isFinite(val) ? val : 0;
  const r = 42, c = 2 * Math.PI * r, offset = c - (displayVal / 100) * c;
  return (
    <div className="relative w-28 h-28 shrink-0">
      <svg viewBox="0 0 100 100" className="w-full h-full -rotate-90">
        <circle cx="50" cy="50" r={r} fill="none" stroke={LINE} strokeWidth="7" />
        <circle cx="50" cy="50" r={r} fill="none" stroke={BLUE} strokeWidth="7" strokeDasharray={c} strokeDashoffset={offset} strokeLinecap="round" style={{ transition: "stroke-dashoffset 0.2s linear" }} />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-lg font-bold" style={{ color: TEXT }}>{displayVal.toFixed(2)}%</span>
      </div>
      <div className="text-center mt-1 text-[10px] uppercase tracking-wide" style={{ color: TEXT_DIM }}>{label}</div>
    </div>
  );
}

/* ============================== PROFILE FRAME ============================== */
function ProfileFrame() {
  const [imgError, setImgError] = useState(false);
  const wrapRef = useRef(null);
  const onMove = (e) => {
    const el = wrapRef.current; if (!el) return;
    const rect = el.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width - 0.5;
    const py = (e.clientY - rect.top) / rect.height - 0.5;
    el.style.transform = `perspective(800px) rotateY(${px * 6}deg) rotateX(${-py * 6}deg)`;
  };
  const onLeave = () => { if (wrapRef.current) wrapRef.current.style.transform = "perspective(800px) rotateY(0) rotateX(0)"; };
  const orbitIcons = [Code2, Database, Cpu, Braces, GitBranch, Binary];

  const corner = (pos) => {
    const base = { position: "absolute", width: 22, height: 22, borderColor: LAVENDER };
    const styles = {
      tl: { top: -10, left: -10, borderTop: "2px solid", borderLeft: "2px solid" },
      tr: { top: -10, right: -10, borderTop: "2px solid", borderRight: "2px solid" },
      bl: { bottom: -10, left: -10, borderBottom: "2px solid", borderLeft: "2px solid" },
      br: { bottom: -10, right: -10, borderBottom: "2px solid", borderRight: "2px solid" },
    };
    return { ...base, ...styles[pos], borderColor: LAVENDER };
  };

  return (
    <div className="relative w-full flex items-center justify-center py-8">
      <div className="absolute w-72 h-72 sm:w-80 sm:h-80 rounded-full spin-slow" style={{ border: `1px dashed ${LINE}` }} />
      <div className="absolute w-72 h-72 sm:w-80 sm:h-80 spin-slow">
        {orbitIcons.map((Icon, i) => {
          const angle = (i / orbitIcons.length) * 2 * Math.PI;
          const radius = 150;
          const x = Math.cos(angle) * radius, y = Math.sin(angle) * radius;
          return (
            <div key={i} className="absolute w-9 h-9 rounded-lg flex items-center justify-center spin-slow-rev"
              style={{ left: `calc(50% + ${x}px - 18px)`, top: `calc(50% + ${y}px - 18px)`, backgroundColor: PANEL_SOLID, border: `1px solid ${LINE}` }}>
              <Icon size={15} style={{ color: LAVENDER }} />
            </div>
          );
        })}
      </div>

      <div ref={wrapRef} onMouseMove={onMove} onMouseLeave={onLeave}
        className="relative w-52 h-64 sm:w-56 sm:h-72"
        style={{ transition: "transform 0.2s ease" }}>
        <div style={corner("tl")} /><div style={corner("tr")} /><div style={corner("bl")} /><div style={corner("br")} />
        <div className="w-full h-full rounded-2xl overflow-hidden relative"
          style={{ padding: 3, background: `linear-gradient(135deg, ${BLUE}, ${LAVENDER})`, boxShadow: "0 24px 60px -20px rgba(0,0,0,0.5)" }}>
          <div className="w-full h-full rounded-[13px] overflow-hidden flex items-center justify-center" style={{ backgroundColor: PANEL_SOLID }}>
            {!imgError ? (
              <img src={profilePhotoHref} alt="Chithra S" onError={() => setImgError(true)} className="w-full h-full object-cover" />
            ) : (
              <div className="flex flex-col items-center justify-center">
                <User size={44} style={{ color: LAVENDER }} />
                <span className="text-2xl font-bold mt-1" style={{ color: TEXT }}>CS</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

