function StickySubNav({ items }) {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <div className="sticky top-0 z-40 -mx-6 px-6 py-3 mb-10 flex gap-5 overflow-x-auto"
      style={{
        backgroundColor: scrolled ? "rgba(8,13,22,0.9)" : "transparent",
        backdropFilter: scrolled ? "blur(10px)" : "none",
        borderBottom: scrolled ? `1px solid ${LINE}` : "1px solid transparent",
        transition: "all 0.25s ease",
      }}>
      {items.map(({ id, label }) => (
        <button key={id} onClick={() => scrollToId(id)} className="text-xs font-medium whitespace-nowrap shrink-0"
          style={{ color: TEXT_DIM }}>
          {label}
        </button>
      ))}
    </div>
  );
}

