/* ============================== SKILL / CERT CARDS ==============================
   Each item owns its own useReveal hook instance. Calling hooks directly inside
   a .map() in a component that can also take other render branches (like the
   view switch in PortfolioApp) breaks React's rules of hooks — the number of
   hooks called must be identical on every render of the same component
   instance. Extracting these into their own components fixes that. */
function SkillPill({ label, accent, delay, inView, onClick }) {
  return (
    <button
      onClick={onClick}
      className="skill-pill inline-flex items-center text-[11px] sm:text-xs font-semibold uppercase tracking-wide px-3 py-2 rounded-lg cursor-pointer"
      style={{
        color: accent,
        border: `1px solid ${accent}55`,
        backgroundColor: `${accent}14`,
        letterSpacing: "0.04em",
        opacity: inView ? 1 : 0,
        transform: inView ? "translateY(0) scale(1)" : "translateY(8px) scale(0.9)",
        transitionDelay: `${delay}s`,
        transitionProperty: "opacity, transform, background-color, border-color",
        transitionDuration: "0.4s",
        transitionTimingFunction: "cubic-bezier(.22,.68,.31,1)",
      }}
    >
      {label}
    </button>
  );
}

function SkillBranchGroup({ groups, accent, inView, align = "left", onSelect }) {
  let idx = 0;
  return (
    <div className={`flex flex-col gap-4 ${align === "right" ? "items-start md:items-end" : "items-start"}`}>
      {groups.map((group) => (
        <div key={group.title} className={align === "right" ? "md:text-right" : ""}>
          <div className="text-[10px] font-semibold uppercase mb-2" style={{ color: TEXT_FAINT, letterSpacing: "0.12em" }}>{group.title}</div>
          <div className={`flex flex-wrap gap-2 ${align === "right" ? "md:justify-end" : ""}`}>
            {group.items.map((it) => {
              const d = 0.05 * idx++;
              return <SkillPill key={it} label={it} accent={accent} delay={d} inView={inView} onClick={() => onSelect(it)} />;
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

