class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error, info) {
    console.error("Portfolio crashed:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ minHeight: "100vh", backgroundColor: NAVY, color: TEXT, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, textAlign: "center" }}>
          <div>
            <p style={{ marginBottom: 16 }}>Something went wrong loading this view.</p>
            <button
              onClick={() => this.setState({ hasError: false })}
              style={{ padding: "10px 20px", borderRadius: 8, backgroundColor: BLUE, color: "#fff", border: "none", fontWeight: 600 }}
            >
              Try again
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function Portfolio() {
  return (
    <ErrorBoundary>
      <PortfolioApp />
    </ErrorBoundary>
  );
}

